// Erasure needs a named actor and a stated ground. An erasure request with
// neither is indistinguishable from someone quietly deleting an inconvenient
// review, and the trail row this leaves behind is only worth keeping if it
// says who asked and why.
const body = $('Webhook erase').first().json.body || {};

const employeeId = (body.employee_id || '').trim();
const reviewer = (body.reviewer || '').trim();
const reason = (body.reason || '').trim();

if (!employeeId || !reviewer) {
  return [{ json: { __http_status: 400, ok: false, error: 'invalid_erase_request', detail: 'employee_id and reviewer are both required' } }];
}
if (reason !== 'subject_request' && reason !== 'retention_expired') {
  return [{ json: { __http_status: 400, ok: false, error: 'invalid_reason', detail: 'reason must be subject_request or retention_expired' } }];
}

return [{ json: {
  __http_status: 200,
  ok: true,
  employee_id: employeeId,
  reviewer,
  reason,
  diff: JSON.stringify({ erased_employee_id: employeeId, reason })
} }];
